/// One plan as the console list renders it.
///
/// The counts ride **this** row rather than being fetched per plan: the list re-fetches on
/// every filter change, and a count per row turns one query into eleven whose answers can
/// disagree with the page they decorate.
#[derive(Debug, Serialize)]
pub struct PlanSummary {
    /// Plan identity.
    pub id: Uuid,
    /// Title, which is the prompt's own first clause until the model names it.
    pub title: String,
    /// Lifecycle state.
    pub status: String,
    /// Which attempt within a chain.
    pub plan_version: i32,
    /// The frozen model.
    pub model_label: String,
    /// Who asked.
    pub created_by: Option<Uuid>,
    /// Artifacts of every kind.
    pub artifact_count: i64,
    /// Artifacts the reviewer resolved.
    pub accepted_count: i64,
    /// Artifacts the reviewer refused or a regeneration retired.
    pub rejected_count: i64,
    /// Artifacts still waiting.
    pub pending_count: i64,
    /// Artifacts the validator refused.
    pub invalid_count: i64,
    /// What it cost in cents.
    pub cost_cents: i32,
    /// Why generation failed or the plan was rejected.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
    /// Row creation.
    #[serde(with = "time::serde::rfc3339")]
    pub created_at: OffsetDateTime,
}

impl PlanSummary {
    fn build(plan: &builder::AppBuilderPlan, counts: &builder::PlanCounts) -> Self {
        Self {
            id: plan.id,
            title: plan.title.clone(),
            status: plan.status.clone(),
            plan_version: plan.plan_version,
            model_label: plan.model_label.clone(),
            created_by: plan.created_by,
            artifact_count: counts.artifacts,
            accepted_count: counts.accepted,
            rejected_count: counts.rejected,
            pending_count: counts.pending,
            invalid_count: counts.invalid,
            cost_cents: plan.cost_cents,
            error: plan.error.clone(),
            created_at: plan.created_at,
        }
    }
}

/// The list, plus what the filter bar draws itself from.
#[derive(Debug, Serialize)]
pub struct PlanListBody {
    /// The page's rows.
    pub plans: Vec<PlanSummary>,
    /// How many rows match the filter, ignoring the page window.
    pub total: i64,
    /// Every status a plan may hold, for the filter's select.
    pub statuses: Vec<&'static str>,
    /// How many rows a page holds by default.
    pub page_size: i64,
}

/// One artifact as the review tree and the detail pane render it.
#[derive(Debug, Serialize)]
pub struct ArtifactBody {
    /// Artifact identity.
    pub id: Uuid,
    /// Which kind.
    pub kind: String,
    /// Stable key within (plan, kind).
    pub key: String,
    /// The artifact this one hangs off.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parent_key: Option<String>,
    /// Order in the tree.
    pub ordinal: i32,
    /// Where the reviewer has got to.
    pub status: String,
    /// The artifact itself.
    pub spec: Value,
    /// The model's own explanation.
    pub rationale: String,
    /// What the validator said, `{ path, message }` each.
    pub validation: Value,
    /// Why the reviewer refused it.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rejected_reason: Option<String>,
    /// The version this one replaced.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub supersedes_id: Option<Uuid>,
    /// Last write.
    #[serde(with = "time::serde::rfc3339")]
    pub updated_at: OffsetDateTime,
}

impl ArtifactBody {
    fn build(artifact: &builder::AppBuilderArtifact) -> Self {
        Self {
            id: artifact.id,
            kind: artifact.kind.clone(),
            key: artifact.key.clone(),
            parent_key: artifact.parent_key.clone(),
            ordinal: artifact.ordinal,
            status: artifact.status.clone(),
            spec: artifact.spec.clone(),
            rationale: artifact.rationale.clone(),
            validation: artifact.validation.clone(),
            rejected_reason: artifact.rejected_reason.clone(),
            supersedes_id: artifact.supersedes_id,
            updated_at: artifact.updated_at,
        }
    }
}

/// One plan with everything the review screen draws.
#[derive(Debug, Serialize)]
pub struct PlanBody {
    /// The plan itself.
    pub plan: PlanSummary,
    /// Its artifacts, ordered the way the tree groups them.
    pub artifacts: Vec<ArtifactBody>,
    /// The counters the footer renders.
    pub counts: builder::PlanCounts,
    /// What stands between the plan and apply, named.
    ///
    /// **Not derived by the client.** The blockers are a property of the plan's whole set —
    /// including a required kind no artifact row could express — so a client that re-derived
    /// the rule would have to re-implement it and would eventually disagree with apply.
    pub blockers: Vec<BlockedBody>,
    /// Whether every required artifact is resolved, i.e. whether the Apply button may be offered.
    pub applicable: bool,
    /// Why the whole plan was rejected or generation failed.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub decision_reason: Option<String>,
    /// When apply finished, `null` until then.
    #[serde(with = "time::serde::rfc3339::option")]
    pub applied_at: Option<OffsetDateTime>,
}

/// One blocker, as the footer's summary list renders it.
#[derive(Debug, Serialize)]
pub struct BlockedBody {
    /// Which kind.
    pub kind: String,
    /// Its key, empty when the plan never proposed that kind at all.
    pub key: String,
    /// Why it blocks: `rejected`, `invalid`, `pending` or `missing`.
    pub status: String,
    /// The first finding or the reviewer's reason.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reason: Option<String>,
}

/// What the landing page shows before it knows whether a provider is connected.
#[derive(Debug, Serialize)]
pub struct VocabularyBody {
    /// The click-to-fill sample prompts.
    pub examples: Vec<ExampleBody>,
    /// Every artifact kind, in the order the tree groups them.
    pub kinds: Vec<&'static str>,
    /// Every artifact status.
    pub statuses: Vec<&'static str>,
    /// Every plan status, for the filter.
    pub plan_statuses: Vec<&'static str>,
    /// The field types a generated entity may declare.
    pub field_types: Vec<&'static str>,
    /// The longest a prompt may be.
    pub max_prompt_len: usize,
}

/// One worked example.
#[derive(Debug, Serialize)]
pub struct ExampleBody {
    /// The chip's label.
    pub title: &'static str,
    /// The prompt to fill the composer with.
    pub prompt: &'static str,
}

/// What an accept, reject or edit answers.
#[derive(Debug, Serialize)]
pub struct ArtifactDecisionBody {
    /// The artifact as it now reads, so the client never re-fetches to draw the new state.
    pub artifact: ArtifactBody,
    /// The plan's counters, so the footer moves without a second round trip.
    pub counts: builder::PlanCounts,
    /// The blockers after the decision, because accepting one artifact usually removes one.
    pub blockers: Vec<BlockedBody>,
}

/// What rejecting or deleting a plan answers.
#[derive(Debug, Serialize)]
pub struct PlanDecisionBody {
    /// The plan as it now reads.
    pub plan: PlanSummary,
}

