/// What the console list asks for. Every field is optional and every field is in the URL, so
/// a reload and the QA walkthrough land on the same view.
#[derive(Debug, Default, Deserialize)]
pub struct PlanListQuery {
    /// Restrict to one status.
    pub status: Option<String>,
    /// Free text over title and prompt.
    pub q: Option<String>,
    /// "Mine only".
    pub mine: Option<bool>,
    /// Restrict to one author.
    pub by: Option<Uuid>,
    /// Organization, for a platform account.
    pub organization_id: Option<Uuid>,
    /// Rows to skip.
    pub offset: Option<i64>,
    /// Rows to return.
    pub limit: Option<i64>,
}

/// The generate form's body.
#[derive(Debug, Deserialize)]
pub struct GenerateBody {
    /// The operator's sentence.
    pub prompt: String,
    /// `provider/model`, or absent for the installation's default.
    pub model: Option<String>,
    /// A human's name for the plan; the model's wins when it sends one.
    pub title: Option<String>,
    /// Organization, for a platform account.
    pub organization_id: Option<Uuid>,
}

/// The edit form's body.
#[derive(Debug, Deserialize)]
pub struct EditArtifactBody {
    /// The artifact's new body. Anything the validator refuses lands as `invalid`, never as
    /// `edited`, so a review screen cannot render a broken artifact as "fixed".
    pub spec: Value,
}

/// The reject form's body.
#[derive(Debug, Deserialize)]
pub struct RejectBody {
    /// Why. Required by the store, and by the request: a bare rejection is a decision nobody
    /// can learn from.
    pub reason: String,
}

